function iconSvg(name,size=18){const paths=ICON_PATHS[name]||ICON_PATHS['check-circle'];return `<svg class="task-svg-icon" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths}</svg>`;}
function inferTaskIcon(name=''){const s=String(name).toLowerCase();const rules=[[/قرآن|كتاب|قراءة|حفظ|درس|علم|مذاكرة|تعلم/,'book-open'],[/صلاة|ذكر|دعاء|عبادة|مسجد|شرع/,'prayer'],[/زوج|أسرة|أبناء|طفل|عائلة|صديق|تواصل/,'users'],[/منزل|بيت|ترتيب|تنظيف|غسيل|صيانة/,'home'],[/طعام|وجبة|طبخ|مطبخ|غذاء/,'utensils'],[/رياضة|مشي|تمرين|حركة|صحة|نوم/,'activity'],[/مال|ميزانية|ادخار|مصروف|دخل/,'wallet'],[/عمل|مهنة|مشروع|عميل|طلب|مبيعات/,'briefcase'],[/تصميم|موشن|فيديو|محتوى|نشر/,'video'],[/وقت|تقويم|موعد|مراجعة/,'calendar'],[/فكرة|ابتكار|تطوير|إبداع/,'lightbulb'],[/تسوق|شراء|مشتريات/,'shopping']];return (rules.find(([re])=>re.test(s))||[])[1]||'target';}
function openBalanceDB(){if(!('indexedDB'in window))return Promise.resolve(null);if(idbDb)return Promise.resolve(idbDb);return new Promise(resolve=>{const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains('state'))db.createObjectStore('state');};req.onsuccess=()=>{idbDb=req.result;resolve(idbDb);};req.onerror=()=>resolve(null);});}
function idbRead(){return openBalanceDB().then(db=>new Promise(resolve=>{if(!db)return resolve(null);const tx=db.transaction('state','readonly'),r=tx.objectStore('state').get('main');r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>resolve(null);}));}
function idbWrite(value){return openBalanceDB().then(db=>new Promise(resolve=>{if(!db)return resolve(false);const tx=db.transaction('state','readwrite');tx.objectStore('state').put(value,'main');tx.oncomplete=()=>resolve(true);tx.onerror=()=>resolve(false);}));}
function migrateState(raw){const s=raw||{};s.schemaVersion=2;s.profile=s.profile||{};s.profile.name=s.profile.name||'صاحب الخطة';s.profile.dailyGoal=Number(s.profile.dailyGoal)||3;s.profile.restDays=s.profile.restDays||['fri'];s.profile.vacationRanges=s.profile.vacationRanges||[];s.theories=normalizeTemplate({theories:(s.theories||[]).map(th=>({...th,sections:(th.sections||[]).map(sec=>({...sec,tasks:(sec.tasks||[]).map(normalizeNode)}))}))}).theories;s.logs=s.logs||[];s.journal=s.journal||{};s.goals=s.goals||[];s.rewards=s.rewards||[];s.redemptions=s.redemptions||[];s.bonuses=s.bonuses||{};s.challengeAwards=s.challengeAwards||{};s.focus=s.focus||{};s.dailyPlans=s.dailyPlans||{};s.inbox=s.inbox||[];s.reviewQueue=s.reviewQueue||[];s.postponements=s.postponements||{};s.settings=s.settings||{};s.settings.modules=Object.assign({focus:true,analytics:true,rewards:true,goals:true,plans:true,habits:true,journal:true},s.settings.modules||{});s.settings.theme=s.settings.theme||'auto';s.settings.zenMode=!!s.settings.zenMode;s.settings.oneHanded=!!s.settings.oneHanded;s.xp=Math.max(0,Number(s.xp)||0);s.coins=Math.max(0,Number(s.coins)||0);return s;}

