  $('saveSettings').addEventListener('click',saveSettings);$('exportBackup').addEventListener('click',exportBackup);$('importBackup').addEventListener('change',importBackup);$('exportCSV').addEventListener('click',exportCSV);$('exportICS').addEventListener('click',exportICS);$('exportTPConfig').addEventListener('click',exportTimePlannerConfig);$('exportTimePlanner').addEventListener('click',exportTimePlannerDB);$('importTPDb').addEventListener('change',importTimePlannerDb);$('resetApp').addEventListener('click',resetApp);
